package org.apache.druid.server.metrics;

import com.google.inject.Inject;
import com.google.inject.Injector;
import org.apache.druid.discovery.NodeRole;
import org.apache.druid.guice.annotations.Self;
import org.apache.druid.java.util.emitter.service.ServiceEmitter;
import org.apache.druid.java.util.emitter.service.ServiceMetricEvent;
import org.apache.druid.java.util.metrics.AbstractMonitor;
import org.apache.druid.query.DruidMetrics;

import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicLong;

public class WorkerTaskCountStatsMonitor extends AbstractMonitor
{
  private final WorkerTaskCountStatsProvider statsProvider;
  private final IndexerTaskCountStatsProvider indexerStatsProvider;
  private final String workerCategory;
  private final String workerVersion;
  private final boolean isMiddleManager;

  @Inject
  public WorkerTaskCountStatsMonitor(
      Injector injector,
      @Self Set<NodeRole> nodeRoles
  )
  {
    this.isMiddleManager = nodeRoles.contains(NodeRole.MIDDLE_MANAGER);
    if (isMiddleManager) {
      this.statsProvider = injector.getInstance(WorkerTaskCountStatsProvider.class);
      this.indexerStatsProvider = null;
      this.workerCategory = statsProvider.getWorkerCategory();
      this.workerVersion = statsProvider.getWorkerVersion();
    } else {
      this.indexerStatsProvider = injector.getInstance(IndexerTaskCountStatsProvider.class);
      this.statsProvider = null;
      this.workerCategory = null;
      this.workerVersion = null;
    }
  }

  @Override
  public boolean doMonitor(ServiceEmitter emitter)
  {
    if (isMiddleManager) {
      emitWorkerTaskCounts(emitter, statsProvider);
    } else {
      emitIndexerTaskCounts(emitter, indexerStatsProvider);
    }
    return true;
  }

  public static long reportTaskCountDelta(AtomicLong count, AtomicLong lastReported)
  {
    long current = count.get();
    long previous = lastReported.get();
    lastReported.set(current);
    return current - previous;
  }

  public static Long computeIdleTaskSlotCount(WorkerTaskCountStatsProvider provider)
  {
    return Math.max(provider.getWorkerTotalTaskSlotCount() - provider.getWorkerUsedTaskSlotCount(), 0);
  }

  private void emitWorkerTaskCounts(ServiceEmitter emitter, WorkerTaskCountStatsProvider provider)
  {
    final Long failedCount = provider.getWorkerFailedTaskCount();
    final Long successCount = provider.getWorkerSuccessfulTaskCount();
    final Long idleSlotCount = provider.getWorkerIdleTaskSlotCount();
    final Long totalSlotCount = provider.getWorkerTotalTaskSlotCount();
    final Long usedSlotCount = provider.getWorkerUsedTaskSlotCount();
    if (failedCount != null) {
      final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
      builder.setDimension(DruidMetrics.CATEGORY, workerCategory);
      builder.setDimension(DruidMetrics.WORKER_VERSION, workerVersion);
      emitter.emit(builder.setMetric("worker/task/failed/count", failedCount));
    }
    if (successCount != null) {
      final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
      builder.setDimension(DruidMetrics.CATEGORY, workerCategory);
      builder.setDimension(DruidMetrics.WORKER_VERSION, workerVersion);
      emitter.emit(builder.setMetric("worker/task/success/count", successCount));
    }
    if (idleSlotCount != null) {
      final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
      builder.setDimension(DruidMetrics.CATEGORY, workerCategory);
      builder.setDimension(DruidMetrics.WORKER_VERSION, workerVersion);
      emitter.emit(builder.setMetric("worker/taskSlot/idle/count", idleSlotCount));
    }
    if (totalSlotCount != null) {
      final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
      builder.setDimension(DruidMetrics.CATEGORY, workerCategory);
      builder.setDimension(DruidMetrics.WORKER_VERSION, workerVersion);
      emitter.emit(builder.setMetric("worker/taskSlot/total/count", totalSlotCount));
    }
    if (usedSlotCount != null) {
      final ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
      builder.setDimension(DruidMetrics.CATEGORY, workerCategory);
      builder.setDimension(DruidMetrics.WORKER_VERSION, workerVersion);
      emitter.emit(builder.setMetric("worker/taskSlot/used/count", usedSlotCount));
    }
  }

  private void emitIndexerTaskCounts(ServiceEmitter emitter, IndexerTaskCountStatsProvider provider)
  {
    emit(emitter, "worker/task/running/count", provider.getWorkerRunningTasks());
    emit(emitter, "worker/task/assigned/count", provider.getWorkerAssignedTasks());
    emit(emitter, "worker/task/completed/count", provider.getWorkerCompletedTasks());
    emit(emitter, "worker/task/failed/count", provider.getWorkerFailedTasks());
    emit(emitter, "worker/task/success/count", provider.getWorkerSuccessfulTasks());
  }

  public void emit(ServiceEmitter emitter, String metricName, Map<String, Long> dataSourceTaskMap)
  {
    for (Map.Entry<String, Long> dataSourceTaskCount : dataSourceTaskMap.entrySet()) {
      if (dataSourceTaskCount.getValue() != null) {
        ServiceMetricEvent.Builder builder = new ServiceMetricEvent.Builder();
        builder.setDimension(DruidMetrics.DATASOURCE, dataSourceTaskCount.getKey());
        emitter.emit(builder.setMetric(metricName, dataSourceTaskCount.getValue()));
      }
    }
  }
}

